livestream:
body{margin:0;background:#ffffff}
a{color:inherit;text-decoration:none}
*{box-sizing:border-box}
html{scrollbar-width:none}html::-webkit-scrollbar{display:none}
.wrap{max-width:1240px;margin:0 auto;padding-left:clamp(20px,4vw,40px);padding-right:clamp(20px,4vw,40px)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:16px 28px;font-size:16px;font-weight:700;border-radius:6px;border:0;cursor:pointer;font-family:inherit;white-space:nowrap;transition:transform .2s ease,box-shadow .2s ease}
.btn:hover{transform:translateY(-1px)}
.gold{color:#1c1405;background:linear-gradient(180deg,#FFEC80 0%,#FFD600 45%,#F5C800 100%);box-shadow:inset 0 1px 0 rgba(255,255,255,.8),inset 0 -2px 0 rgba(160,100,0,.3),0 6px 16px rgba(16,24,40,.16)}
.ghost{color:#0A0A0A;background:#F1F1F1;box-shadow:inset 0 1px 0 rgba(255,255,255,.9)}
.white{color:#0f1720;background:#ffffff;box-shadow:inset 0 -2px 0 rgba(16,24,40,.08),0 6px 16px rgba(16,24,40,.18)}
.dark{color:#ffffff;background:#0f1720}
.h1{margin:0;font-size:clamp(38px,5.2vw,72px);line-height:1.02;font-weight:800;letter-spacing:-.045em}
.h2{margin:0;font-size:clamp(30px,3.6vw,48px);line-height:1.06;font-weight:800;letter-spacing:-.035em;color:#0f1720}
.sub{margin:14px 0 0;font-size:clamp(17px,1.4vw,20px);line-height:1.55;font-weight:400;color:#475467}
.sec{padding-top:clamp(64px,8vw,104px);padding-bottom:clamp(64px,8vw,104px)}
.tint{background:#F5F5F5}
.shot{display:block;width:100%;height:100%;object-fit:cover;border-radius:8px;box-shadow:0 1px 2px rgba(16,24,40,.06),0 18px 40px rgba(16,24,40,.14)}
/* header */
.hdr{position:sticky;top:0;z-index:20;background:rgba(255,255,255,.88);-webkit-backdrop-filter:saturate(180%) blur(16px);backdrop-filter:saturate(180%) blur(16px);box-shadow:0 1px 0 rgba(16,24,40,.06)}
.hdr .wrap{padding-top:calc(env(safe-area-inset-top) + 10px);padding-bottom:10px;display:flex;align-items:center;justify-content:space-between;gap:20px}
.hdr nav{display:flex;align-items:center;gap:clamp(16px,2.4vw,32px);font-size:15px;font-weight:500;color:#344054}
.navlink.on{color:#0A0A0A;font-weight:700}
.menubtn{display:none;width:44px;height:44px;align-items:center;justify-content:center;padding:0;background:none;border:0;cursor:pointer}
.menu{position:fixed;inset:0;z-index:50;background:#ffffff;display:flex;flex-direction:column;padding:calc(env(safe-area-inset-top) + 10px) 20px calc(env(safe-area-inset-bottom) + 24px)}
.menu .mtop{display:flex;align-items:center;justify-content:space-between;height:56px}
.menu .mlinks{margin-top:24px;display:flex;flex-direction:column}
.mlab{font-size:11px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;color:#98a2b3;margin-bottom:12px}
.mgrid{display:flex;flex-direction:column;gap:10px}
.msvc{display:flex;align-items:center;gap:16px;padding:6px 0}
.msvc img{flex:none;width:88px;height:64px;object-fit:cover;border-radius:4px}
.msvc span{display:flex;flex-direction:column;font-size:21px;font-weight:600;letter-spacing:-.02em;color:#0f1720}
.msvc small{margin-top:2px;font-size:13px;font-weight:400;letter-spacing:0;color:#667085;line-height:1.4}
.mmore{display:flex;flex-direction:column}
.mmore a{padding:10px 0;font-size:17px;font-weight:500;color:#344054}
.menu .mlinks a{display:flex;align-items:center;gap:16px;padding:18px 4px;font-size:22px;font-weight:600;border-bottom:2px solid #ECECEC}
/* service picker */
.pick{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}
.pcard{display:flex;flex-direction:column;overflow:hidden;border-radius:8px;background:#ffffff;box-shadow:0 1px 2px rgba(16,24,40,.06),0 14px 34px rgba(16,24,40,.12);transition:transform .35s cubic-bezier(.2,.7,.2,1),box-shadow .35s}
.pcard:hover{transform:translateY(-6px);box-shadow:0 2px 4px rgba(16,24,40,.06),0 28px 56px rgba(16,24,40,.2)}
.pimg{position:relative;display:block;height:clamp(150px,12vw,180px);overflow:hidden}
.pimg img{width:100%;height:100%;object-fit:cover;transition:transform .9s cubic-bezier(.2,.7,.2,1)}
.pcard:hover .pimg img{transform:scale(1.06)}
.pbody{padding:20px 20px 22px;display:flex;flex-direction:column;flex:1}
.pbody>a{display:block;min-height:40px}
.pbody h2{margin:0;font-size:24px;font-weight:700;letter-spacing:-.03em}
.pbody p{margin:6px 0 0;font-size:15px;line-height:1.5;color:#475467}
.pact{margin-top:auto;padding-top:18px;display:flex;align-items:center;justify-content:space-between;gap:12px}
.pdet{display:inline-flex;align-items:center;height:42px;padding:0 16px;border-radius:6px;background:#F1F1F1;font-size:15px;font-weight:600;color:#0A0A0A}
.pbook{padding:11px 22px!important;font-size:15px!important}
.badge{position:absolute;left:14px;top:14px;display:flex;align-items:center;gap:7px;padding:7px 11px;border-radius:8px;background:rgba(10,10,10,.78);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);font-size:12px;font-weight:700;letter-spacing:.08em;color:#fff}
.badge i{width:7px;height:7px;border-radius:50%;background:#FFD600;animation:pulse 1.4s ease-in-out infinite}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.35}}
/* includes + add-ons */
.incs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));column-gap:40px;row-gap:36px}
.incwrap{display:grid;grid-template-columns:minmax(0,6fr) minmax(0,7fr);gap:clamp(32px,4vw,56px);align-items:center}
.incwrap .incs{grid-template-columns:repeat(2,minmax(0,1fr))}
.incimg{aspect-ratio:16/10}
.inc{display:grid;grid-template-columns:36px 1fr;column-gap:16px}
.inc svg{grid-row:span 2;width:32px;height:32px}
.inc h3{margin:2px 0 0;font-size:19px;font-weight:700;letter-spacing:-.02em}
.inc p{margin:4px 0 0;font-size:15px;line-height:1.5;color:#475467}
.ads{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:56px;row-gap:0}
.ad{display:grid;grid-template-columns:36px 1fr;column-gap:16px;padding:24px 0;border-top:2px solid #ECECEC}
.ad svg{width:30px;height:30px}
.ad h3{margin:2px 0 0;font-size:19px;font-weight:700;letter-spacing:-.02em}
.ad p{margin:6px 0 0;font-size:15px;line-height:1.55;color:#475467}
.trust{margin-top:32px;display:flex;gap:clamp(20px,3vw,40px)}
.trust div{display:flex;flex-direction:column}
.trust b{font-size:clamp(24px,2.4vw,32px);font-weight:700;letter-spacing:-.03em;color:#0A0A0A}
.trust span{font-size:14px;color:#475467}
.quote{display:flex;flex-wrap:wrap;gap:clamp(24px,4vw,56px);align-items:center}
.quote blockquote{margin:0;font-size:clamp(24px,2.6vw,34px);line-height:1.3;font-weight:500;letter-spacing:-.025em}
/* gallery */
.gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
.gallery img{height:280px}
/* faq */
.faq details{border-bottom:2px solid #ECECEC}
.faq summary{list-style:none;cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:22px 0;font-size:19px;font-weight:600;letter-spacing:-.01em}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after{content:"";flex:none;width:11px;height:11px;border-right:2.5px solid #0A0A0A;border-bottom:2.5px solid #0A0A0A;transform:rotate(45deg) translateY(-3px);transition:transform .25s}
.faq details[open] summary::after{transform:rotate(-135deg) translateY(-3px)}
.faq p{margin:0 0 22px;font-size:16px;line-height:1.6;color:#475467;max-width:640px}
/* ideas */
.ideas{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));grid-auto-rows:250px;gap:20px}
.idea{position:relative;display:block;overflow:hidden;border-radius:8px;isolation:isolate;box-shadow:0 1px 2px rgba(16,24,40,.06),0 16px 36px rgba(16,24,40,.12);transition:transform .45s cubic-bezier(.2,.7,.2,1),box-shadow .45s}
.idea:hover{transform:translateY(-6px);box-shadow:0 2px 4px rgba(16,24,40,.06),0 28px 56px rgba(16,24,40,.2)}
.idea img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2;transition:transform 1s cubic-bezier(.2,.7,.2,1)}
.idea:hover img{transform:scale(1.05)}
.ishade{position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(10,10,10,0) 20%,rgba(10,10,10,.72) 52%,rgba(10,10,10,.95) 100%)}
.icap{position:absolute;left:24px;right:24px;bottom:22px;color:#fff}
.isvc{font-size:13px;font-weight:700;letter-spacing:.06em;color:#FFD600}
.icap h3{margin:6px 0 0;font-size:23px;font-weight:700;letter-spacing:-.03em;line-height:1.12}
.icap p{margin:6px 0 0;font-size:15px;line-height:1.45;color:rgba(255,255,255,.9)}
.i1{grid-column:1 / 8;grid-row:span 2}.i1 h3{font-size:clamp(28px,2.8vw,38px)}
.i2,.i3{grid-column:8 / 13}.i4{grid-column:1 / 5}.i5{grid-column:5 / 9}.i6{grid-column:9 / 13}
.marq{display:flex;width:max-content;animation:marq 40s linear infinite}
.marq img{height:46px;width:auto;margin:0 34px;mix-blend-mode:multiply;filter:grayscale(1);opacity:.85}
@keyframes marq{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.pkgrid{margin-top:36px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(24px,4vw,56px)}
.pkimg{aspect-ratio:16/9}
