@keyframes rise{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:none}}
.r1{animation:rise .8s .05s cubic-bezier(.2,.7,.2,1) both}.r2{animation:rise .8s .16s cubic-bezier(.2,.7,.2,1) both}.r3{animation:rise .8s .28s cubic-bezier(.2,.7,.2,1) both}
