.navlink.on{color:#0A0A0A;font-weight:700}
.menubtn{display:none;width:44px;height:44px;align-items:center;justify-content:center;padding:0;background:none;border:0;cursor:pointer}
.menu{position:fixed;inset:0;z-index:50;background:#ffffff;display:flex;flex-direction:column;padding:calc(env(safe-area-inset-top) + 10px) 20px calc(env(safe-area-inset-bottom) + 24px)}
.menu .mtop{display:flex;align-items:center;justify-content:space-between;height:56px}
.menu .mlinks{margin-top:24px;display:flex;flex-direction:column}
.mlab{font-size:11px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;color:#98a2b3;margin-bottom:12px}
.mgrid{display:flex;flex-direction:column;gap:10px}
.msvc{display:flex;align-items:center;gap:16px;padding:6px 0}
