.menu .mlinks a{display:flex;align-items:center;gap:16px;padding:18px 4px;font-size:22px;font-weight:600;border-bottom:2px solid #ECECEC}
/* service picker */
.pick{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}
.pcard{display:flex;flex-direction:column;overflow:hidden;border-radius:8px;background:#ffffff;box-shadow:0 1px 2px rgba(16,24,40,.06),0 14px 34px rgba(16,24,40,.12);transition:transform .35s cubic-bezier(.2,.7,.2,1),box-shadow .35s}
.pcard:hover{transform:translateY(-6px);box-shadow:0 2px 4px rgba(16,24,40,.06),0 28px 56px rgba(16,24,40,.2)}
.pimg{position:relative;display:block;height:clamp(150px,12vw,180px);overflow:hidden}
.pimg img{width:100%;height:100%;object-fit:cover;transition:transform .9s cubic-bezier(.2,.7,.2,1)}
.pcard:hover .pimg img{transform:scale(1.06)}
.pbody{padding:20px 20px 22px;display:flex;flex-direction:column;flex:1}
.pbody>a{display:block;min-height:40px}
